{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Repirinast, a structurally related chromone-like dicarboxylate, showed very low systemic availability after oral dosing in a volunteer, with plasma concentrations below the quantification limit.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Cromolyn, a close chemical relative with two carboxylates and no basic center, has less than 1% absorption from a swallowed dose in humans, directly supporting low oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Pefloxacin, a quinolone with one carboxylate and a basic piperazine, has 100% oral bioavailability, but this is weakly transferable to the query because the query lacks the basic amine and has two carboxylates.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar dicarboxylic acid chromone-like mast cell stabilizer. The closest experimental analogues, repirinast and cromolyn, show very low or ~1% oral systemic availability, directly supporting F < 20%. High-bioavailability quinolones are less transferable because they contain a basic amine and only one carboxylate, so they do not override the low-F evidence.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule is present in the provided evidence.",
    "Morgan similarities to the closest low-F analogues are modest (0.31 and 0.26), so quantitative transfer is uncertain.",
    "The high-F quinolone evidence is structurally distant and lacks the dicarboxylate/polyanionic character of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

